@compute @workgroup_size(1, 1, 1)
@override_workgroup_size(1, 1, 1)
fn main(@builtin(global_invocation_id) global_id : vec3<u32>) {
  let i : u32 = global_id.x;
  if (i >= params.length) {
    return;
  }
  let x = left_values[i];
  let y = right_values[i];
  let abs_x = abs(x);
  let sqrt_abs_x = sqrt(abs_x);
  let result = if (x < 0.0) { -sqrt_abs_x } else { sqrt_abs_x };
  let out_idx = params.output_offset + i;
  output_values[out_idx] = result;
}

